using System.IO;
using SoopaDriveTool.Core;
using SoopaDriveTool.Windows;
partial class Program
{
    static async Task V10MigrationChecks(string root,bool browseOnly=false)
    {
        if(Environment.MachineName!="SDTLAB"&&Environment.GetEnvironmentVariable("GITHUB_ACTIONS")!="true")throw new Exception("Owned spare/CI only.");string vhd=Path.Combine(root,"migration-owned.vhd"),browse=Path.Combine(root,"browse-owned-é-测试.vhd");int number=-1;
        async Task<DiskInfo> Current()=>(await StorageService.InventoryAsync()).Single(d=>d.Number==number);
        async Task Apply(OperationKind kind,PartitionInfo? part=null,Func<DiskOperation,DiskOperation>? edit=null){var d=await Current();var op=DiskOperation.For(d,kind,part);await StorageService.ExecuteDetailedAsync(edit?.Invoke(op)??op);}
        try
        {
            string script=Path.Combine(root,"migration-create.txt");await File.WriteAllTextAsync(script,$"create vdisk file=\"{vhd}\" maximum=2048 type=expandable\nselect vdisk file=\"{vhd}\"\nattach vdisk\nexit\n");string response=await StorageService.PowerShellAsync($"diskpart.exe /s '{script}';(Get-DiskImage -ImagePath '{vhd}'|Get-Disk).Number");number=int.Parse(response.Split('\n').Last().Trim());var d=await Current();Check(d.Bus=="File Backed Virtual"&&!d.Protected,"Migration tests use a separate owned VHD");await Apply(OperationKind.InitializeGpt);await Apply(OperationKind.CreatePartition,edit:o=>o with{Bytes=512L*1024*1024,Value="Left"});await Apply(OperationKind.CreatePartition,edit:o=>o with{Bytes=512L*1024*1024,Value="Right"});d=await Current();PartitionInfo left=d.Partitions.First(p=>p.Label=="Left"),right=d.Partitions.First(p=>p.Label=="Right");await File.WriteAllTextAsync(Path.Combine(left.Letter+@":\","left.txt"),"Left preserved bytes");await File.WriteAllTextAsync(Path.Combine(right.Letter+@":\","right.txt"),"Right preserved bytes");await File.WriteAllTextAsync(Path.Combine(right.Letter+@":\","right.txt")+":Proof","Donor stream");
            if(!browseOnly){
            await Apply(OperationKind.SplitPartition,left,o=>o with{Bytes=384L*1024*1024,Value="Split",Workspace=root});d=await Current();left=d.Partitions.First(p=>p.Label=="Left");var split=d.Partitions.First(p=>p.Label=="Split");Check(left.Size==384L*1024*1024&&split.Offset==left.Offset+left.Size&&await File.ReadAllTextAsync(Path.Combine(left.Letter+@":\","left.txt"))=="Left preserved bytes","NTFS split creates the reviewed adjacent partition while retaining original files");await File.WriteAllTextAsync(Path.Combine(split.Letter+@":\","split.txt"),"Merged preserved bytes");
            await Apply(OperationKind.MergePartition,left,o=>o with{TargetPartitionNumber=split.Number,Workspace=root});d=await Current();left=d.Partitions.First(p=>p.Label=="Left");string merged=Directory.GetDirectories(left.Letter+@":\","Merged-*").Single();Check(left.Size==512L*1024*1024&&await File.ReadAllTextAsync(Path.Combine(merged,"split.txt"))=="Merged preserved bytes","Adjacent merge restores source contents into a unique destination subfolder");right=d.Partitions.First(p=>p.Label=="Right");await Apply(OperationKind.RedistributeSpace,left,o=>o with{Bytes=64L*1024*1024,TargetPartitionNumber=right.Number,Workspace=root});d=await Current();left=d.Partitions.First(p=>p.Label=="Left");right=d.Partitions.First(p=>p.Label=="Right");Check(left.Size==576L*1024*1024&&right.Size==448L*1024*1024&&await File.ReadAllTextAsync(Path.Combine(right.Letter+@":\","right.txt"))=="Right preserved bytes"&&await File.ReadAllTextAsync(Path.Combine(right.Letter+@":\","right.txt")+":Proof")=="Donor stream","Redistribution shrinks, moves and grows real NTFS volumes without losing donor data or streams");
            // Convert a representable, ordinary file tree; NTFS-only streams block conversion.
            await RejectAsync(()=>Apply(OperationKind.ChangeFileSystem,right,o=>o with{FileSystem="exFAT",Workspace=root}),"Filesystem conversion rejects alternate streams before formatting");File.Delete(Path.Combine(right.Letter+@":\","right.txt")+":Proof");await Apply(OperationKind.ChangeFileSystem,right,o=>o with{FileSystem="exFAT",Workspace=root});d=await Current();right=d.Partitions.First(p=>p.Offset==right.Offset);Check(right.FileSystem=="exFAT"&&await File.ReadAllTextAsync(Path.Combine(right.Letter+@":\","right.txt"))=="Right preserved bytes","NTFS-to-exFAT migration preserves representable file contents through a verified checkpoint");
            }
            await Apply(OperationKind.Offline);d=await Current();string repo=Path.Combine(root,"browse-vault");string id=await ProtectedImageService.CaptureRawAsync(d,repo,"browse image passphrase","Full");await ImageBrowseService.MountReadOnlyAsync(repo,"browse image passphrase",id,browse);string state=await StorageService.PowerShellAsync($"$d=Get-DiskImage -ImagePath '{browse}'|Get-Disk;@{{ReadOnly=$d.IsReadOnly;Size=$d.Size}}|ConvertTo-Json -Compress");Check(state.Contains("true",StringComparison.OrdinalIgnoreCase),"Protected raw image attaches as a genuinely read-only browsing VHD");await ImageBrowseService.DetachAsync(browse);
            var benchmark=await BenchmarkService.RunAsync(root,64,1,1,"Custom",false,false,null,CancellationToken.None,[new("Custom 64K",65536,2,1,true,70)]);Check(benchmark.Results.Count==1&&benchmark.Workloads?.Single().BlockBytes==65536&&benchmark.Profile=="Custom"&&benchmark.Results[0].MBps>0,"A real custom DiskSpd workload uses the requested block size, queue and read mix");
        }
        finally{foreach(string image in new[]{browse,vhd})if(File.Exists(image)){try{using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(30));await StorageService.PowerShellAsync($"Dismount-DiskImage -ImagePath '{image}' -ErrorAction Stop",timeout.Token);}catch{}}}
    }
}
